(() => {
  const $ = (s, root=document) => root.querySelector(s);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const profileKey='vayu-profile-id';
  let userId=localStorage.getItem(profileKey); if(!userId){userId='profile_'+crypto.randomUUID().replaceAll('-','');localStorage.setItem(profileKey,userId)}
  let displayName=localStorage.getItem('vayu-display-name')||'Community member';
  let air=null, reports=[], pageName='home', reportFilter='all', communityMode='connect', campusMe=null;
  const titles={home:['AIR INTELLIGENCE · COMMUNITY ACTION','Home'],air:['UNDERSTAND YOUR AIR','AQI Intelligence'],connect:['CONNECT YOUR COMMUNITY','VAYU CONNECT'],campus:['EMPOWER STUDENTS','VAYU CAMPUS'],myreports:['YOUR REPORT LOG','My Reports'],settings:['PREFERENCES','Settings']};
  async function api(path, options={}, extra={}) { options={...options,...extra,headers:{...(options.headers||{}),...(extra.headers||{})}}; const res=await fetch(path,options); let data={}; try{data=await res.json()}catch{} if(!res.ok)throw Error(data.detail||data.message||`Request failed (${res.status})`); return data }
  const json=(method, body)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200)}
  function person(){return {user_id:userId,display_name:displayName}}
  function setTop(){const [crumb,title]=titles[pageName]||titles.home;$('#crumb').textContent=crumb;$('#title').textContent=title;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===pageName));$('#home-view').style.display=pageName==='home'?'':'none';$('#detail').style.display=pageName==='home'?'none':''}
  function go(view){if(view==='community')view='connect';if(!titles[view])return;pageName=view;if(view==='connect')communityMode='connect';if(view==='campus')communityMode='campus';setTop();if(view==='home')renderHome();if(view==='connect'||view==='campus')renderCommunity();if(view==='air')renderAir();if(view==='myreports')renderMine();if(view==='settings')renderSettings();window.scrollTo({top:0,behavior:'smooth'})}
  function freshness(data){const v=data?.current?.timestamp||data?.retrieved_at;if(!v)return 'No current reading';const age=(Date.now()-new Date(v).getTime())/3600000;return age>3?`Updated ${new Date(v).toLocaleString()} · may be stale`:`Updated ${new Date(v).toLocaleString()}`}
  function kindLabel(kind){return ({observed:'Observed',estimated:'Estimated',forecast:'Forecast',scenario:'Scenario',unavailable:'Unavailable'})[kind]||'Unavailable'}
  function valueText(value, unit='µg/m³'){return value===null||value===undefined?'—':`${Number(value).toFixed(1)} <small>${unit}</small>`}
  function airSummary(){if(!air||!air.current){return `<div class="air-summary-empty"><p>There is no current air reading available for ${esc(air?.location||'the configured location')} right now.</p><button class="button button-secondary" data-action="refresh">Try again</button></div>`}const x=air.current,label=kindLabel(x.kind||air.data_kind),aqi=x.aqi??air.aqi;return `<div class="air-summary-grid"><div class="air-summary-lead"><span class="data-badge ${esc((x.kind||air.data_kind)||'unavailable')}">${esc(label)}</span><div class="air-summary-number">${x.pm25==null?'—':Number(x.pm25).toFixed(1)} <small>µg/m³</small></div><span class="air-summary-label">PM₂.₅</span></div><div class="air-summary-metrics"><div><span>PM₁₀</span><b>${x.pm10==null?'—':Number(x.pm10).toFixed(1)} <small>µg/m³</small></b></div><div><span>AQI</span><b>${aqi==null?'Unavailable':esc(aqi)}</b></div></div><div class="air-summary-meta"><span>${esc(air.source||'Source unavailable')} · ${esc(air.location||'Location unavailable')}</span><span>${x.timestamp?esc(new Date(x.timestamp).toLocaleString()):'Timestamp unavailable'}</span></div>${air.tomorrow_forecast?`<div class="home-forecast"><span class="data-badge forecast">Forecast · ${esc(air.tomorrow_forecast.date)}</span><b>PM₂.₅ ${Number(air.tomorrow_forecast.pm25_mean).toFixed(1)} µg/m³</b><small>Provider outlook · not a guaranteed outcome</small></div>`:''}</div>`}
  function updateAirHeader(){const box=$('#home-air-summary');if(box)box.innerHTML=airSummary();$('#home-location').textContent=air?.location||'your configured location';$('#freshness').textContent=air?freshness(air):'Air data unavailable';$('#location-label').textContent=`⌖ ${air?.location||'Delhi'}`;$('#provider-status').textContent=air?.status==='available'?'Connected':'Unavailable'; }
  async function loadAir(){try{air=await api('/api/air-quality/latest')}catch(e){air={status:'unavailable',data_kind:'unavailable',label:e.message,current:null}}updateAirHeader();if(pageName==='air')renderAir()}
  async function loadReports(){try{const data=await api('/api/environment/reports');reports=data.reports||[]}catch{reports=[]}}
  const statusText=s=>({submitted:'Submitted',under_review:'Under review',action_reported:'Action reported',awaiting_verification:'Awaiting verification',verified_resolved:'Verified resolved',closed_without_verification:'Closed without verification',claimed:'Under review',action_started:'Action reported',resolution_submitted:'Awaiting verification',resolved:'Awaiting verification'})[s]||s||'Unknown';
  const categoryText=s=>({garbage:'Garbage',waste_burning:'Waste burning',construction_dust:'Construction dust',smoke:'Smoke',other:'Other'})[s]||s;
  function reportCard(r, mine=false){return `<article class="report-card"><div class="report-card-top"><span class="tag">${esc(categoryText(r.category))}</span><span class="tag status">${esc(statusText(r.status))}</span></div><h3>${esc(r.reference||`VAYU-${String(r.id).padStart(6,'0')}`)}</h3><p>${esc(r.description)}</p><div class="meta">${esc(r.city)} · ${esc(new Date(r.created_at).toLocaleString())}${r.latitude!=null?` · ⌖ ${Number(r.latitude).toFixed(2)}, ${Number(r.longitude).toFixed(2)}`:''}</div>${r.photo_url?`<img class="report-photo" src="${esc(r.photo_url)}" alt="Photo attached to report">`:''}<div class="report-card-actions">${mine?`<span>Community responses: ${Number(r.observed_count||0)} observed · ${Number(r.dispute_count||0)} disputed</span>`:`<button class="text-button" data-action="respond" data-id="${r.id}" data-kind="observed">I’ve seen this</button><button class="text-button" data-action="respond" data-id="${r.id}" data-kind="dispute">Dispute</button>`}<button class="text-button" data-action="details" data-id="${r.id}">Details</button></div>${mine?`<div class="meta">Reference: ${esc(r.reference)} · Tracking uses this browser profile, not a login.</div>`:''}</article>`}
  function empty(text){return `<div class="empty-state">${esc(text)}</div>`}
  async function renderHome(){await Promise.all([loadAir(),loadReports()]);if(pageName!=='home')return;let activities=[];try{activities=(await api('/api/community/activities')).activities||[]}catch{}const reportItems=reports.slice(0,3).map(r=>`<article class="preview-item">${r.photo_url?`<img loading="lazy" decoding="async" src="${esc(r.photo_url)}" alt="Photo submitted with ${esc(r.reference)}">`:''}<div><span class="tag status">${esc(statusText(r.status))}</span><span class="tag">${esc(categoryText(r.category))}</span><h3>${esc(r.reference)}</h3><p>${esc(r.description)}</p><small>${esc(r.city)} · ${esc(new Date(r.created_at).toLocaleDateString())}</small></div></article>`);const activityItems=activities.slice(0,3).map(x=>`<article class="preview-item">${x.has_image?`<img loading="lazy" decoding="async" src="/api/community/activities/${x.id}/image" alt="Approved activity: ${esc(x.name)}">`:''}<div><span class="tag">Approved activity</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><small>${esc(x.city)} · ${Number(x.interest_count)} expressed interest</small></div></article>`);const items=[...reportItems,...activityItems].slice(0,3);$('#home-community-preview').innerHTML=items.length?items.join(''):empty('No community reports or approved activities yet. Start by sharing a local environmental concern.')}
  function renderAir(){const data=air||{};const current=data.current||{};const unit='µg/m³';const points=data.series||[];const path=points.length>1?svgLine(points.map(p=>Number(p.pm25))):'';$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">${esc(kindLabel(current.kind||data.data_kind).toUpperCase())}</div><h2>How polluted is the air?</h2><p>Air-quality values for ${esc(data.location||'the configured location')}. Modelled estimates and station observations are kept separate.</p></section><section class="air-grid"><article class="metric-card primary-metric"><div class="eyebrow">PM₂.₅</div><div class="metric-value">${valueText(current.pm25,unit)}</div><p>${esc(kindLabel(current.kind||data.data_kind))}</p></article><article class="metric-card"><div class="eyebrow">PM₁₀</div><div class="metric-value">${valueText(current.pm10,unit)}</div><p>${esc(kindLabel(current.kind||data.data_kind))}</p></article><article class="metric-card"><div class="eyebrow">AQI</div><div class="metric-value">${data.aqi??current.aqi??'—'}</div><p>${data.aqi??current.aqi?'Provided value':'Unavailable for this source'}</p></article></section><section class="panel"><div class="section-head"><div><div class="eyebrow">RECENT AIR INFORMATION</div><h2>PM₂.₅ trend</h2><p>${esc(freshness(data))}</p></div><span class="tag">${esc(kindLabel(current.kind||data.data_kind))}</span></div>${path?`<div class="chart-wrap"><svg class="trend-chart" viewBox="0 0 700 220" role="img" aria-label="PM2.5 values over the last available 48 hours"><path class="chart-fill" d="${path} L680 190 L20 190 Z"/><path class="chart-line" d="${path}"/></svg></div><div class="data-note">Each point comes from Open-Meteo modelled grid estimates. It is not a monitoring-station reading.</div>`:empty('A trend needs at least two available readings. No values have been filled in.')}</section>${data.tomorrow_forecast?`<section class="panel forecast-panel"><div class="eyebrow">FORECAST · ${esc(data.tomorrow_forecast.date)}</div><h2>Tomorrow’s PM₂.₅ outlook</h2><p>Estimated daily average: <b>${Number(data.tomorrow_forecast.pm25_mean).toFixed(1)} ${unit}</b> · range ${Number(data.tomorrow_forecast.pm25_min).toFixed(1)}–${Number(data.tomorrow_forecast.pm25_max).toFixed(1)} · ${Number(data.tomorrow_forecast.hours)} provider hours.</p><div class="data-note">Provider forecast, not an observed measurement. No AQI forecast is available.</div></section>`:''}<section class="data-note">Source: ${esc(data.source||'Unavailable')} · Location: ${esc(data.location||'Not configured')}${current.timestamp?` · Timestamp: ${esc(new Date(current.timestamp).toLocaleString())}`:''}<br>${esc(data.label||data.error||'No data available.')}</section>`;appendCampusHistory()}
  function svgLine(vals){const clean=vals.filter(Number.isFinite);if(clean.length<2)return '';const max=Math.max(...clean,1),min=Math.min(...clean);return clean.map((v,i)=>`${i?'L':'M'} ${20+i*660/(clean.length-1)} ${180-(v-min)/(max-min||1)*140}`).join(' ')}
  async function renderConnect(){await loadReports();if(!['connect','community'].includes(pageName))return;let groups=[],activities=[];try{groups=(await api('/api/community/communities')).groups||[]}catch{}try{activities=(await api('/api/community/activities')).activities||[]}catch{}const active=reportFilter==='all'?reports:reportFilter==='nearby'?reports.filter(r=>(r.city||'').toLowerCase()===(air?.location||'').toLowerCase()):reportFilter==='open'?reports.filter(r=>['submitted','under_review'].includes(r.status)):reportFilter==='community_action'?reports.filter(r=>['action_reported','awaiting_verification'].includes(r.status)):reportFilter==='resolved'?reports.filter(r=>['verified_resolved','closed_without_verification'].includes(r.status)):reports.filter(r=>r.status===reportFilter);$('#module-content').innerHTML=`<section class="page-intro"><div class="eyebrow">CITIZEN ENVIRONMENTAL COMMUNITY</div><h2>Your Neighbourhood. Your Voice.</h2><p>Report local concerns, find community-led action and follow each report through its real review status.</p><div class="hero-actions"><button class="button button-primary" data-action="new-report">Report an issue</button><button class="button button-secondary" data-action="new-activity">Propose an activity</button></div><p class="data-note">For fires, hazardous materials, or immediate danger, keep your distance and contact local emergency services. This app does not submit official complaints.</p></section><section class="panel"><div class="section-head"><div><h2>Community Hazard Radar</h2><p>Reports use approximate public coordinates. The plot below is not a street map.</p></div><select id="report-filter" aria-label="Filter reports"><option value="all">All reports</option><option value="nearby">Near configured city</option><option value="open">Open issues</option><option value="community_action">Community action</option><option value="resolved">Closed issues</option><option value="submitted">Needs a volunteer</option><option value="under_review">Under review</option><option value="action_reported">Action reported</option><option value="awaiting_verification">Awaiting verification</option><option value="verified_resolved">Verified resolved</option><option value="closed_without_verification">Closed without verification</option></select></div><div class="coordinate-plot" id="coordinate-plot" role="img" aria-label="Local coordinate plot of reported issues">${plotReports(active)}</div><div class="report-list">${active.length?active.map(r=>reportCard(r)).join(''):empty('No reports in this view. Missing reports remain empty until someone submits one.')}</div></section><section class="panel"><div class="section-head"><div><h2>Approved local activities</h2><p>Join counts show self-reported interest, not verified attendance or impact.</p></div><button class="button button-secondary" data-action="new-activity">Propose an activity</button></div>${activities.length?`<div class="group-grid">${activities.map(x=>`<article class="group-card">${x.has_image?`<img loading="lazy" decoding="async" class="report-photo" src="/api/community/activities/${x.id}/image" alt="Photo for ${esc(x.name)}">`:''}<span class="tag">${esc(x.category)}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="meta">${esc(x.city)} · ${esc(new Date(x.starts_at).toLocaleString())}</div><div class="meta">${Number(x.interest_count)} expressed interest</div><button class="text-button" data-action="join-activity" data-id="${x.id}">I can help</button></article>`).join('')}</div>`:empty('No approved activities yet. New proposals remain private until reviewed.')}</section><section class="panel"><div class="section-head"><div><div class="eyebrow">FIND YOUR COMMUNITY</div><h2>Local groups</h2><p>Groups are community-submitted and not independently verified.</p></div><button class="button button-secondary" data-action="new-group">Add group</button></div>${groups.length?`<div class="group-grid">${groups.map(g=>`<article class="group-card"><h3>${esc(g.name)}</h3><p>${esc(g.description)}</p><div class="meta">${esc(g.city)} · Community-submitted</div></article>`).join('')}</div>`:empty('No groups have been added yet.')}</section>`;$('#report-filter').value=reportFilter;$('#report-filter').addEventListener('change',e=>{reportFilter=e.target.value;renderCommunity()})}
  function communityTabs(){return `<div class="community-tabs" role="tablist"><button class="button ${communityMode==='connect'?'button-primary':'button-secondary'}" data-action="community-connect">VAYU CONNECT <small>Local citizen action</small></button><button class="button ${communityMode==='campus'?'button-primary':'button-secondary'}" data-action="community-campus">VAYU CAMPUS <small>Verified college network</small></button></div>`}
  async function renderCommunity(){if(communityMode==='campus'){await campusPublic();return}$('#detail').innerHTML='<div id="module-content"></div>';await renderConnect()}
  async function campusPublic(){let me=null,colleges=[],campaigns=[],projects=[],reportsForCampus=[],myApplications={college_applications:[],student_applications:[]};try{me=await api('/api/campus/me')}catch{}if(me){try{myApplications=await api('/api/campus/my-applications')}catch{}}try{colleges=(await api('/api/campus/colleges')).colleges||[]}catch{}try{campaigns=(await api('/api/campus/campaigns')).campaigns||[]}catch{}try{projects=(await api('/api/campus/projects')).projects||[]}catch{}try{reportsForCampus=(await api('/api/environment/reports')).reports||[]}catch{}campusMe=me;
    const auth=me?`<div class="campus-auth"><span>Signed in as <b>${esc(me.name)}</b> · ${esc(me.role)}</span><button class="text-button" data-action="campus-logout">Sign out</button></div>`:`<form class="campus-auth campus-form" data-form="auth"><h3>Sign in or create an account</h3><input name="name" placeholder="Your name (for new account)" minlength="2"><input name="email" type="email" required placeholder="Email"><input name="password" type="password" required minlength="12" placeholder="Password (12+ characters)"><button class="button button-primary" type="submit">Create account</button><button class="button button-secondary" type="button" data-action="campus-login">Sign in instead</button><small>Student and college access requires review. Verification documents stay private.</small></form>`;
    const ownApplications=[...(myApplications.college_applications||[]).map(x=>({name:x.college_name,city:x.city,status:x.status,reason:x.rejection_reason})),...(myApplications.student_applications||[]).map(x=>({name:x.college_name,city:'Student membership',status:x.status,reason:x.rejection_reason}))];const ownStatus=ownApplications.length?`<section class="panel application-status"><div class="eyebrow">YOUR APPLICATIONS</div><div class="application-status-list">${ownApplications.map(x=>`<div><b>${esc(x.name)}</b><span>${esc(x.city)}</span><span class="status-pill ${esc(x.status)}">${esc(({pending:'Pending review',under_review:'Under review',approved:'Approved',rejected:'Not approved'}[x.status]||x.status))}</span>${x.reason?`<small>${esc(x.reason)}</small>`:''}</div>`).join('')}</div></section>`:'';const collegeCards=colleges.map(c=>`<article class="group-card"><span class="tag">Approved college</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="meta">${esc(c.city)} · ${esc((c.focus||[]).join(', ')||'Environmental action')}</div><div class="meta">${c.approved_campaigns} approved campaigns · ${c.verified_observations} quality-checked observations</div><button class="text-button" data-action="student-apply" data-id="${c.id}">Apply to join</button></article>`).join('');
    const campCards=campaigns.map(c=>`<article class="report-card"><span class="tag">${esc(c.category)}</span><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="meta">${esc(c.college_name||'VAYURAKSHAK')} · ${esc(c.city)} · ${esc(c.starts_at)} to ${esc(c.ends_at)}</div><p>${esc(c.objective)}</p><div class="meta">${c.participating_colleges} participating colleges · approved campaign</div>${me?.role==='student'?`<button class="button button-secondary" data-action="join-campaign" data-id="${c.id}">Join with my college</button><button class="button button-secondary" data-action="completion-evidence" data-id="${c.id}">Upload activity evidence</button>`:''}</article>`).join('');
    $('#detail').innerHTML=`<section class="campus-hero"><div class="campus-art" role="img" aria-label="Illustration of students working together in a campus garden"></div><div class="campus-hero-copy"><div class="eyebrow">VERIFIED INTER-COLLEGE NETWORK</div><h2>Small Campus Actions.<br>A Bigger Environmental Impact.</h2><p>Connect students and colleges through environmental observation, collaboration and reviewed clean-air initiatives.</p><div class="hero-actions"><button class="button button-primary" data-action="campus-explore">Explore Campus Network <span>→</span></button><button class="button button-secondary" data-action="show-college-form">Apply for College Approval</button></div></div></section>${auth}${ownStatus}<section class="panel campus-mission"><div class="eyebrow">DIWALI CLEAN-AIR MISSION</div><h2>One festival. Multiple colleges. One clean-air mission.</h2><p>One festival. Multiple colleges. One clean-air mission. Public campaigns appear after administrator approval; air readings retain their source labels.</p><div class="data-note">Campus-specific forecasts and cross-college AQI comparison are not yet available. AQI predictions are for the server-configured location only.</div></section><section class="panel campus-issues"><div class="section-head"><div><div class="eyebrow">CITIZEN REPORTS</div><h2>Issues shared by the community</h2><p>Public reports can help students discover local concerns. They remain citizen-submitted and follow their displayed review status.</p></div><button class="button button-secondary" data-go="connect">Open VAYU CONNECT</button></div><div class="report-list">${reportsForCampus.length?reportsForCampus.slice(0,4).map(r=>reportCard(r)).join(''):empty('No community reports are available yet.')}</div></section><section class="panel"><div class="section-head"><div><h2>Approved colleges</h2><p>Discover verified college communities; private student details are not shown.</p></div><input id="campus-search" placeholder="Search college or city" aria-label="Search approved colleges"></div><div class="group-grid">${collegeCards||empty('No college communities are approved yet.')}</div></section><section class="panel"><div class="section-head"><div><h2>Approved campaigns</h2><p>Every public campaign is reviewed by VAYURAKSHAK.</p></div></div><div class="report-list">${campCards||empty('No approved campaigns yet.')}</div></section>${me?campusForms(me,colleges):''}<section class="panel"><h2>Approved student projects</h2><div class="group-grid">${projects.map(p=>`<article class="group-card"><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="meta">${esc(p.topic)} · ${esc(p.college||'Student community')}</div></article>`).join('')||empty('No projects have passed review yet.')}</div></section><section class="panel admin-panel"><h2>Administrator review</h2><p>Admin access is available only when VAYU_ADMIN_TOKEN is configured on the server.</p><div class="admin-access"><input id="admin-key" type="password" autocomplete="off" placeholder="Administrator token"><button class="button button-secondary" data-action="admin-open">Open review queue</button></div><div id="admin-queue"></div></section>`;
    document.querySelectorAll('#detail .report-card').forEach(function(card){const item=campaigns.find(function(x){return card.textContent.includes(x.name)});if(item&&item.has_image){const img=document.createElement('img');img.className='report-photo';img.src='/api/campus/campaigns/'+item.id+'/image';img.alt='Approved campus activity';card.insertBefore(img,card.querySelector('.meta'))}});await appendCampusHistory();await appendLeaderboard();await appendCampusImpact();$('#campus-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#detail .group-card').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(q))})}
  async function appendCampusImpact(){let d;try{d=await api('/api/campus/impact')}catch{return}const section=document.createElement('section');section.className='panel';section.innerHTML='<h2>Campus contribution snapshot</h2><div class="impact-grid"><b>'+Number(d.approved_colleges||0)+'<small>approved colleges</small></b><b>'+Number(d.approved_campaigns||0)+'<small>approved campaigns</small></b><b>'+Number(d.verified_activities||0)+'<small>verified activities</small></b><b>'+Number(d.approved_student_memberships||0)+'<small>approved student memberships</small></b><b>'+Number(d.quality_checked_observations||0)+'<small>quality-checked observations</small></b></div><div class="data-note">'+esc(d.methodology||'Only reviewed records are counted; no pollution reduction is estimated.')+'</div>';$('#detail').append(section)}
  async function appendLeaderboard(){let data;try{data=await api('/api/campus/leaderboard')}catch{return}const section=document.createElement('section');section.className='panel';const rows=(data.colleges||[]).map(function(c,i){return '<tr><td>'+String(i+1)+'</td><td>'+esc(c.name)+' · '+esc(c.city)+'</td><td>'+c.verified_activities+'</td><td>'+c.quality_observations+'</td><td>'+c.approved_campaigns+'</td></tr>'}).join('');section.innerHTML='<h2>Inter-college recognition</h2><p>Ranked from reviewed contributions only; no pollution reduction score.</p><div class="table-scroll"><table><thead><tr><th>Rank</th><th>College</th><th>Verified activities</th><th>Quality-checked observations</th><th>Approved campaigns</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="data-note">'+esc(data.methodology||'Counts are separate and do not estimate emissions impact.')+'</div>';$('#detail').append(section)}
  async function appendCampusHistory(){let data;try{data=await api('/api/historical/coverage')}catch{return}const section=document.createElement('section');section.className='panel campus-history';const opts=(data.observations||[]).map(function(x){return '<option value="'+encodeURIComponent(x.city)+'|'+encodeURIComponent(x.station)+'">'+esc(x.city)+' · '+esc(x.station)+' ('+esc((x.available_diwali_years||[]).join(', ')||'no Diwali-period coverage')+')</option>'}).join('');section.innerHTML='<div class="section-head"><div><h2>Diwali AQI Watch</h2><p>Compare imported station observations before, during and after Diwali.</p></div><button class="button button-secondary" data-action="open-aqi">Current air →</button></div><div class="campus-history-controls"><select id="hist-station"><option value="">Select city and station</option>'+opts+'</select><select id="hist-years" multiple aria-label="Select at least two years"><option value="2022">2022</option><option value="2023">2023</option><option value="2024">2024</option><option value="2025">2025</option><option value="2026">2026</option></select><select id="hist-days"><option value="1">1 day before and after</option><option selected value="3">3 days before and after</option><option value="7">7 days before and after</option></select><button class="button button-primary" data-action="compare-diwali">Compare years</button></div><div class="data-note">Only observed imported station records are used; missing dates remain missing. 2026 is upcoming/partial until measurements exist. Source labels are uploader-supplied.</div><div id="hist-result">'+((data.observations||[]).length?'Choose a city/station and at least two years.':'No historical station records have been imported.')+'</div>';$('#detail').append(section)}
  async function compareDiwali(){const pair=$('#hist-station')?.value;if(!pair)throw Error('Choose a city and station');const years=[...($('#hist-years')?.selectedOptions||[])].map(x=>x.value);if(years.length<2)throw Error('Select at least two years');const parts=pair.split('|').map(decodeURIComponent);const qs=new URLSearchParams({city:parts[0],station:parts[1],years:years.join(','),days:$('#hist-days').value});const data=await api('/api/historical/diwali?'+qs.toString());$('#hist-result').innerHTML='<p>'+esc(data.summary?.pm25?.message||'Comparison calculated from available records.')+'</p>'+data.results.map(function(y){const before=y.windows.before,during=y.windows.during,after=y.windows.after,cmp=y.comparisons.pm25;return '<article class="review-card"><b>'+y.year+' · Diwali '+esc(y.festival_date)+'</b><p>PM₂.₅ µg/m³ — before: '+(before.metrics.pm25.mean??'no data')+' ('+before.metrics.pm25.valid_days+'/'+before.expected_days+' days) · during: '+(during.metrics.pm25.mean??'no data')+' ('+during.metrics.pm25.valid_days+'/'+during.expected_days+' days) · after: '+(after.metrics.pm25.mean??'no data')+' ('+after.metrics.pm25.valid_days+'/'+after.expected_days+' days)</p><p>PM₁₀: '+(during.metrics.pm10.mean??'no data')+' · AQI: '+(during.metrics.aqi.mean??'no data')+' · '+esc(cmp.status==='compared'?'Before vs Diwali: '+cmp.change_percent.toFixed(1)+'%':cmp.reason||'Comparison unavailable')+'</p><small>'+esc([...(during.sources||[])].join(', ')||'No source record during Diwali day')+' · '+esc(during.start)+' to '+esc(during.effective_end||during.end)+' · '+esc(during.status)+'</small></article>'}).join('')+'<div class="data-note">Comparison window spans '+data.days_each_side+' day(s) on either side. Descriptive observations do not prove cause.</div>'}
  function campusForms(me,colleges){if(me.role!=='student')return `<section class="panel"><h2>College registration</h2><p>Apply on behalf of a college. A private verification document is required. Only approved applications appear publicly.</p><form class="campus-form" data-form="college"><input name="college_name" required minlength="3" placeholder="College name"><input name="city" required minlength="2" placeholder="City"><input name="official_email" type="email" placeholder="Official college email (optional)"><input name="representative" required placeholder="Representative name"><input name="contact" required placeholder="Contact information"><input name="club_details" placeholder="Environmental club details"><input name="focus" placeholder="Focus areas, comma separated"><textarea name="reason" required minlength="15" placeholder="Why should the college join?"></textarea><label>Verification document (PDF/image, max 5 MB)<input name="document" type="file" required accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="button button-primary">Submit college application</button></form></section>`;
    const collegeOptions=colleges.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.city)}</option>`).join('');return `<section class="panel"><h2>Inter-college campaign proposal</h2><p>Requires VAYURAKSHAK administrator approval before public listing.</p><form class="campus-form" data-form="campaign"><select name="college_id" required>${collegeOptions}</select><input name="name" required placeholder="Campaign name"><input name="category" required placeholder="Category (e.g. Diwali awareness)"><input name="city" required placeholder="City"><input name="starts_at" type="date" required><input name="ends_at" type="date" required><textarea name="description" required minlength="15" placeholder="Campaign description"></textarea><textarea name="objective" required minlength="8" placeholder="Objective"></textarea><textarea name="activities" required minlength="5" placeholder="Expected activities"></textarea><label>Optional campaign photo<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="button button-primary">Submit for approval</button></form></section><section class="panel"><h2>VAYU Earth Observatory</h2><p>Observations are separated by method. Photos never become AQI readings. Review labels are not scientific certification.</p><form class="campus-form" data-form="observation"><select name="kind"><option value="visual">Visual observation</option><option value="sensor">Sensor measurement</option><option value="external">External monitoring result</option></select><input name="category" required placeholder="Category"><input name="observed_at" type="datetime-local" required><input name="city" required placeholder="City"><input name="source" required placeholder="Data source or sensor name"><input name="method" required placeholder="Observation method"><input name="pm25" type="number" min="0" step="any" placeholder="PM₂.₅ (sensor/external only)"><input name="pm10" type="number" min="0" step="any" placeholder="PM₁₀ (sensor/external only)"><input name="instrument" placeholder="Instrument"><input name="calibration" placeholder="Calibration details"><textarea name="description" required minlength="8" placeholder="Describe the observation"></textarea><button class="button button-primary">Submit observation for review</button></form><div class="data-note">Research export is limited to reviewed observations and requires administrator credentials. The app is not affiliated with NASA or GLOBE.</div></section><section class="panel"><h2>Student project showcase</h2><form class="campus-form" data-form="project"><input name="title" required placeholder="Project title"><input name="topic" required placeholder="Topic"><input name="url" type="url" placeholder="Optional project link"><textarea name="description" required minlength="20" placeholder="Describe the work"></textarea><button class="button button-primary">Submit project for review</button></form></section>`}
  async function adminQueue(){const token=$('#admin-key')?.value||sessionStorage.getItem('vayu-admin-token')||'';if(!token)throw Error('Enter the configured admin token');sessionStorage.setItem('vayu-admin-token',token);const data=await api('/api/campus/admin/queue',{headers:{'X-Admin-Token':token}});const box=$('#admin-queue');const cards=[];for(const row of data.approved_colleges||[]){cards.push(`<article class=\"review-card\"><b>${esc(row.name)}</b><p>${esc(row.city)} · Approved college</p><button class=\"text-button\" data-action=\"admin-decision\" data-kind=\"college\" data-id=\"${row.application_id}\" data-decision=\"suspend\">Suspend</button><button class=\"text-button\" data-action=\"admin-decision\" data-kind=\"college\" data-id=\"${row.application_id}\" data-decision=\"deactivate\">Deactivate</button></article>`)}for(const [key,title,kind] of [['college_applications','College applications','college'],['student_applications','Student membership','student'],['campaigns','Campaign proposals','campaign'],['observations','Observations','observation'],['projects','Student projects','project'],['completions','Activity evidence','completion'],['community_activities','Community activity proposals','community_activity']]){for(const row of data[key]||[]){cards.push(`<article class="review-card"><b>${esc(row.college_name||row.college||row.college_name||row.college||row.college_name||row.name||row.title||row.campaign_name||row.college_name||row.student_name||row.category||title)}</b><p>${esc(row.reason||row.details||row.description||row.city||'Review submission')}</p>${['college','student','completion','community_activity'].includes(kind)?`<button class="text-button" data-action="admin-doc" data-kind="${kind}" data-id="${row.id}">View private document</button>`:''}${kind==='observation'?`<button class="text-button" data-action="observation-review" data-id="${row.id}" data-status="reviewed">Mark reviewed</button><button class="text-button" data-action="observation-review" data-id="${row.id}" data-status="quality_checks_passed">Quality checks passed</button><button class="text-button" data-action="observation-review" data-id="${row.id}" data-status="rejected">Reject</button>`:`<button class="text-button" data-action="admin-decision" data-kind="${kind}" data-id="${row.id}" data-decision="approve">Approve</button><button class="text-button" data-action="admin-decision" data-kind="${kind}" data-id="${row.id}" data-decision="reject">Reject</button>`}</article>`)}}for(const r of data.reports||[]){cards.push('<article class="review-card"><b>'+esc(categoryText(r.category))+' · '+esc(r.city)+'</b><p>'+esc(r.description)+' · '+esc(r.status)+'</p>'+(r.resolution_photo_url?'<img class="report-photo" src="'+esc(r.resolution_photo_url)+'" alt="Submitted resolution evidence">':'')+(r.status==='awaiting_verification'?'<button class="text-button" data-action="admin-report" data-id="'+r.id+'" data-decision="verify">Verify resolved</button>':'')+'<button class="text-button" data-action="admin-report" data-id="'+r.id+'" data-decision="close">Close without verification</button></article>')}for(const r of data.campaigns||[]){if(r.image_path)cards.push('<article class="review-card">'+esc(r.name||'Campaign')+' <button class="text-button" data-action="admin-doc" data-kind="campaign" data-id="'+r.id+'">Review private campaign photo</button></article>')}for(const r of data.observations||[]){if(r.photo_available)cards.push('<article class="review-card">Observation '+r.id+' <button class="text-button" data-action="admin-doc" data-kind="observation" data-id="'+r.id+'">Review private photo</button></article>')}box.innerHTML=`<div class="admin-review-list">${cards.join('')||empty('No items are waiting for review.')}</div><button class="button button-secondary" data-action="observations-export">Download reviewed observation CSV</button>`}
  function plotReports(list){const coords=list.filter(r=>Number.isFinite(Number(r.latitude))&&Number.isFinite(Number(r.longitude)));if(!coords.length)return '<span>No located reports to plot.</span>';const xs=coords.map(x=>Number(x.longitude)),ys=coords.map(x=>Number(x.latitude)),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);return `<svg viewBox="0 0 700 180" aria-hidden="true">${coords.map((r,i)=>{const x=24+(Number(r.longitude)-xmin)/(xmax-xmin||1)*652,y=18+(ymax-Number(r.latitude))/(ymax-ymin||1)*144;return `<circle cx="${x}" cy="${y}" r="8"><title>${esc(r.reference)} · ${esc(categoryText(r.category))}</title></circle>`}).join('')}</svg><small>${coords.length} approximate report location${coords.length===1?'':'s'}</small>`}
  async function renderMine(){let mine=[];try{mine=(await api(`/api/environment/reports/mine?user_id=${encodeURIComponent(userId)}`)).reports||[]}catch(e){$('#detail').innerHTML=empty(e.message);return}$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">YOUR REPORT LOG</div><h2>My Reports</h2><p>Track reports created from this browser. This profile ID is not an account or secure identity.</p><button class="button button-primary" data-action="new-report">Report an issue</button></section><section class="report-list">${mine.length?mine.map(r=>reportCard(r,true)).join(''):empty('You have not submitted a report from this browser yet.')}</section>`}
  function renderSettings(){const loc=air?.location||'Delhi';$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">APP SETTINGS</div><h2>Settings</h2><p>Simple preferences for this browser.</p></section><section class="panel settings-panel"><label for="display-name">Display name</label><input id="display-name" maxlength="40" value="${esc(displayName)}"><p class="data-note">Used with your pseudonymous report profile. Sign-in and identity verification are not available.</p><button class="button button-primary" data-action="save-settings">Save</button></section><section class="panel"><h2>Air-data location</h2><p>${esc(loc)}</p><div class="data-note">Location is configured by the app server. Current air estimates are requested for this configured location.</div></section>`}
  function showDialog(title,body){const old=$('#app-dialog');if(old)old.remove();const d=document.createElement('dialog');d.id='app-dialog';d.innerHTML=`<div class="dialog-card"><button type="button" class="dialog-close" data-action="dismiss" aria-label="Close">×</button><h2>${esc(title)}</h2><div class="dialog-content">${body}</div></div>`;document.body.append(d);d.showModal()}
  async function createReportForm(){let groups=[];try{groups=(await api('/api/community/communities')).groups||[]}catch{}showDialog('Report an environmental issue',`<form class="report-form"><label>Category<select name="category"><option value="garbage">Garbage</option><option value="waste_burning">Waste burning</option><option value="construction_dust">Construction dust</option><option value="smoke">Smoke</option><option value="other">Other</option></select></label><label>City<input name="city" required minlength="2" value="${esc(air?.location||'Delhi')}"></label><label>What did you notice?<textarea name="description" required minlength="8" maxlength="500"></textarea></label><label>Photo (optional, max 3 MB)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="check-line"><input name="useLocation" type="checkbox"> Add approximate browser location (rounded before saving)</label>${groups.length?`<label>Community group (optional)<select name="group"><option value="">No group</option>${groups.map(g=>`<option value="${g.id}">${esc(g.name)} · ${esc(g.city)}</option>`).join('')}</select></label>`:''}<p class="data-note">Reports are community-submitted and not independently verified. This app does not classify photos with AI.</p><button class="button button-primary" type="button" data-action="submit-report">Check for similar reports</button></form>`)}
  async function submitReport(button){const form=button.closest('form'),fd=new FormData(form);let lat=null,lon=null;if(fd.get('useLocation')){try{const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{timeout:8000}));lat=Number(pos.coords.latitude.toFixed(2));lon=Number(pos.coords.longitude.toFixed(2))}catch{toast('Location was unavailable. Submit without coordinates or try again.');return}}
    const body={...person(),category:fd.get('category'),city:fd.get('city'),description:fd.get('description'),latitude:lat,longitude:lon};if(fd.get('group'))body.community_id=Number(fd.get('group'));
    const match=await api('/api/environment/reports/similar',json('POST',{category:body.category,city:body.city,description:body.description,latitude:lat,longitude:lon}));if(match.matches.length&&!confirm(`Similar recent report${match.matches.length===1?'':'s'} found: ${match.matches.map(x=>x.reference).join(', ')}. Submit a separate report anyway?`))return;
    const file=fd.get('photo');if(file&&file.size){if(file.size>3000000)throw Error('Photo must be 3 MB or smaller');const up=new FormData();up.append('file',file);const image=await api('/api/community/uploads',{method:'POST',body:up});body.photo_url=image.image_url}
    const item=await api('/api/environment/reports',json('POST',body));$('#app-dialog')?.close();toast(`Report ${item.reference} submitted`);go('myreports')}
  async function showDetails(id){const r=await api(`/api/environment/reports/${id}`);showDialog(r.reference,`<span class="tag status">${esc(statusText(r.status))}</span><p>${esc(r.description)}</p><p>${esc(r.city)} · ${esc(categoryText(r.category))}</p><div class="meta">Community responses: ${r.observed_count||0} observed · ${r.dispute_count||0} disputed</div><p class="data-note">Responses are self-reported, not verification.</p><h3>Report history</h3>${(r.history||[]).map(h=>`<p class="history-row"><b>${esc(statusText(h.status))}</b><br><small>${esc(new Date(h.created_at).toLocaleString())}</small></p>`).join('')||'<p>No status history available.</p>'}${r.status==='submitted'?`<button type="button" class="button button-secondary" data-action="claim" data-id="${id}">Volunteer to help</button>`:''}${r.status==='under_review'&&r.claimed_by_id===userId?`<button type="button" class="button button-secondary" data-action="start" data-id="${id}">Mark action started</button>`:''}${r.status==='action_reported'&&r.claimed_by_id===userId?`<label>Resolution photo<input type="file" id="resolution-photo" accept="image/jpeg,image/png,image/webp"></label><label>Note<textarea id="resolution-note" maxlength="300"></textarea></label><button type="button" class="button button-primary" data-action="resolve" data-id="${id}">Submit evidence</button>`:''}`)}
  document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return}const jump=e.target.closest('[data-go]');if(jump){go(jump.dataset.go);return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;try{if(a==='dismiss'){$('#app-dialog')?.close()}if(a==='refresh'){await loadAir();toast('Air data refreshed')}if(a==='new-report')await createReportForm();if(a==='submit-report')await submitReport(b);if(a==='details')await showDetails(id);if(a==='respond'){await api(`/api/environment/reports/${id}/confirm`,json('POST',{...person(),kind:b.dataset.kind}));toast('Response recorded as self-reported');go(pageName)}if(a==='claim'){await api(`/api/environment/reports/${id}/claim`,json('POST',person()));$('#app-dialog')?.close();toast('You accepted this report');go('community')}if(a==='start'){await api(`/api/environment/reports/${id}/start`,json('POST',person()));$('#app-dialog')?.close();toast('Action marked as started');go('community')}if(a==='resolve'){const file=$('#resolution-photo')?.files[0];if(!file)throw Error('Add a resolution photo first');if(file.size>3000000)throw Error('Photo must be 3 MB or smaller');const fd=new FormData();fd.append('file',file);const up=await api('/api/community/uploads',{method:'POST',body:fd});await api(`/api/environment/reports/${id}/resolve`,json('POST',{...person(),resolution_photo_url:up.image_url,resolution_note:$('#resolution-note').value}));$('#app-dialog')?.close();toast('Evidence submitted; awaiting independent verification');go('myreports')}if(a==='new-activity')showDialog('Propose a local activity',`<form class="campus-form" data-form="connect_activity"><input name="name" required minlength=4 maxlength=100 placeholder="Activity name"><select name="category"><option value="cleanup">Clean-up</option><option value="plantation">Plantation</option><option value="awareness">Awareness</option><option value="other">Other</option></select><input name="city" required minlength=2 maxlength=80 value="${esc(air?.location||'Delhi')}" placeholder="City"><label>Date and time<input name="starts_at" type="datetime-local" required></label><textarea name="description" required minlength=15 maxlength=1000 placeholder="What will volunteers do?"></textarea><label>Optional activity photo<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="button button-primary">Submit for review</button><small>Only approved activities become public. Join counts are not verified attendance.</small></form>`);if(a==='join-activity'){await api('/api/community/activities/'+id+'/join',json('POST',person()));toast('Interest recorded; attendance is not verified');renderCommunity()}if(a==='new-group')showDialog('Add a local group',`<form class="group-form"><label>Group name<input name="name" required minlength="3"></label><label>City<input name="city" required minlength="2" value="${esc(air?.location||'Delhi')}"></label><label>About this group<textarea name="description" required minlength="10" maxlength="500"></textarea></label><p class="data-note">Groups are user-submitted and not verified.</p><button type="button" class="button button-primary" data-action="submit-group">Add group</button></form>`);if(a==='submit-group'){const form=b.closest('form'),fd=new FormData(form);await api('/api/community/communities',json('POST',{name:fd.get('name'),city:fd.get('city'),description:fd.get('description')}));$('#app-dialog')?.close();toast('Group added');go('community')}if(a==='save-settings'){displayName=$('#display-name').value.trim()||'Community member';localStorage.setItem('vayu-display-name',displayName);toast('Settings saved')}}catch(err){toast(err.message||'Something went wrong')}});
  function campusStudentApply(id){showDialog('Apply to join this college','<form class="campus-form" data-form="student"><input type="hidden" name="college_id" value="'+esc(id)+'"><input name="official_email" type="email" placeholder="Official college email (if available)"><textarea name="details" required minlength="8" placeholder="Student verification details"></textarea><label>Identity document (private, max 5 MB)<input name="document" type="file" required accept="application/pdf,image/jpeg,image/png,image/webp"></label><button class="button button-primary">Submit membership request</button></form>')}
  async function campusFormSubmit(form){const fd=new FormData(form),kind=form.dataset.form;let result;if(kind==='connect_activity'){const body={user_id:userId,display_name:displayName,name:fd.get('name'),description:fd.get('description'),category:fd.get('category'),city:fd.get('city'),starts_at:new Date(fd.get('starts_at')).toISOString()};const upload=new FormData();upload.append('payload',JSON.stringify(body));const photo=fd.get('photo');if(photo&&photo.size)upload.append('image',photo);result=await api('/api/community/activities',{method:'POST',body:upload})}
    if(kind==='auth'){const body={email:fd.get('email'),password:fd.get('password')};if(form.dataset.mode==='login')result=await api('/api/campus/login',json('POST',body));else result=await api('/api/campus/register',json('POST',{...body,name:fd.get('name')}));toast(form.dataset.mode==='login'?'Signed in':'Account created');renderCommunity();return}
    if(kind==='college'){fd.set('focus',JSON.stringify(String(fd.get('focus')||'').split(',').map(x=>x.trim()).filter(Boolean)));result=await api('/api/campus/college-applications',{method:'POST',body:fd})}
    if(kind==='student')result=await api('/api/campus/student-applications',{method:'POST',body:fd})
    if(kind==='campaign'){const photo=fd.get('photo');const body=Object.fromEntries(fd.entries());delete body.photo;body.college_id=Number(body.college_id);result=await api('/api/campus/campaigns',json('POST',body));if(photo&&photo.size){const upload=new FormData();upload.append('image',photo);await api('/api/campus/campaigns/'+result.id+'/image',{method:'POST',body:upload})}}
    if(kind==='observation'){const body=Object.fromEntries(fd.entries());body.observed_at=new Date(body.observed_at).toISOString();body.pm25=body.pm25===''?null:Number(body.pm25);body.pm10=body.pm10===''?null:Number(body.pm10);const payload=new FormData();payload.append('payload',JSON.stringify(body));result=await api('/api/campus/observations',{method:'POST',body:payload})}
    if(kind==='project')result=await api('/api/campus/projects',json('POST',Object.fromEntries(fd.entries())))
    if(kind==='completion'){const upload=new FormData();upload.append('note',fd.get('note'));upload.append('proof',fd.get('proof'));result=await api('/api/campus/campaigns/'+fd.get('campaign_id')+'/completion',{method:'POST',body:upload})}
    if(kind==='diwali'){result=await api('/api/campus/admin/diwali-mission',json('POST',{city:fd.get('city'),starts_at:fd.get('starts_at'),ends_at:fd.get('ends_at')}),{headers:{'X-Admin-Token':sessionStorage.getItem('vayu-admin-token')}})}
    $('#app-dialog')?.close();toast(result?.message||'Submitted for review');renderCommunity()}
  document.addEventListener('submit',async e=>{const form=e.target.closest('.campus-form');if(!form)return;e.preventDefault();try{await campusFormSubmit(form)}catch(err){toast(err.message||'Could not submit')}});
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
    if(a==='community-campus'){go('campus')}
    if(a==='community-connect'){go('connect')}
    if(a==='campus-login'){const f=b.closest('form');f.dataset.mode='login';f.querySelector('button[type=submit]').textContent='Sign in'}
    if(a==='campus-logout'){await api('/api/campus/logout',{method:'POST'});campusMe=null;toast('Signed out');renderCommunity()}
    if(a==='student-apply')campusStudentApply(b.dataset.id)
    if(a==='completion-evidence')showDialog('Submit campaign activity evidence','<form class=\"campus-form\" data-form=\"completion\"><input type=\"hidden\" name=\"campaign_id\" value=\"'+esc(b.dataset.id)+'\"><textarea name=\"note\" required minlength=\"8\" placeholder=\"What did your college complete?\"></textarea><label>Before/after or activity photo<input name=\"proof\" type=\"file\" required accept=\"image/jpeg,image/png,image/webp\"></label><button class=\"button button-primary\">Submit for review</button></form>');if(a==='show-college-form')document.querySelector('[data-form=college]')?.scrollIntoView({behavior:'smooth'})
    if(a==='campus-explore')document.querySelector('.campus-mission')?.scrollIntoView({behavior:'smooth'});if(a==='open-aqi')go('air')
    if(a==='compare-diwali')await compareDiwali()
    if(a==='join-campaign'){await api('/api/campus/campaigns/'+b.dataset.id+'/join',{method:'POST'});toast('Your college joined this campaign');renderCommunity()}
    if(a==='admin-open')await adminQueue()
    if(a==='admin-decision'){const token=sessionStorage.getItem('vayu-admin-token');const kind=b.dataset.kind;const routes={college:'college-applications',student:'student-applications',campaign:'campaigns',project:'projects',completion:'completions',community_activity:'community-activities'};await api('/api/campus/admin/'+routes[kind]+'/'+b.dataset.id+'/decision',json('POST',{decision:b.dataset.decision,reason:(b.dataset.decision==='approve'?'':prompt('Review or rejection reason (optional)')||'')}),{headers:{'X-Admin-Token':token}});toast('Review decision saved');await adminQueue()}
    if(a==='admin-report'){await api('/api/campus/admin/reports/'+b.dataset.id+'/decision',json('POST',{decision:b.dataset.decision,reason:(b.dataset.decision==='approve'?'':prompt('Review or rejection reason (optional)')||'')}),{headers:{'X-Admin-Token':sessionStorage.getItem('vayu-admin-token')}});toast('Report review saved');await adminQueue()}
    if(a==='observation-review'){await api('/api/campus/admin/observations/'+b.dataset.id+'/review',json('POST',{status:b.dataset.status,note:prompt('Quality review note (optional)')||''}),{headers:{'X-Admin-Token':sessionStorage.getItem('vayu-admin-token')}});toast('Observation review saved');await adminQueue()}
    if(a==='admin-doc'){const res=await fetch('/api/campus/admin/documents/'+b.dataset.kind+'/'+b.dataset.id,{headers:{'X-Admin-Token':sessionStorage.getItem('vayu-admin-token')}});if(!res.ok)throw Error('Private document could not be opened');const blob=await res.blob();window.open(URL.createObjectURL(blob),'_blank','noopener')}
    if(a==='observations-export'){const res=await fetch('/api/campus/observations/export',{headers:{'X-Admin-Token':sessionStorage.getItem('vayu-admin-token')}});if(!res.ok)throw Error('Export unavailable');const blob=await res.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='vayu-campus-reviewed-observations.csv';link.click();URL.revokeObjectURL(url)}
    if(a==='diwali-launch-form')showDialog('Launch the official Diwali mission','<form class="campus-form" data-form="diwali"><input name="city" required value="'+esc(air?.location||'Delhi')+'" placeholder="City"><label>Start<input name="starts_at" type="date" required></label><label>End<input name="ends_at" type="date" required></label><button class="button button-primary">Launch approved mission</button></form>')
  }catch(err){toast(err.message||'Action failed')}});
  document.addEventListener('change',e=>{if(e.target.id==='report-filter'){reportFilter=e.target.value;renderCommunity()}});
  $('#refresh').addEventListener('click',()=>loadAir());
  setTop();renderHome();
})();
